session_start();require_once __DIR__.'/koneksi.php';require_once __DIR__.'/includes/legacy_finance_http.php';require_once __DIR__.'/includes/legacy_operational_tariffs.php';try{lf_http_bootstrap($koneksi);}catch(DomainException $e){http_response_code(403);exit('Akun Super Admin aktif diperlukan.');}
$actor=(int)$_SESSION['admin_id'];$unit=unit_active_id();$student=filter_var($_GET['student']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$error='';$notice='';$preview=null;$values=[];
if(empty($_SESSION['csrf_legacy_tariff']))$_SESSION['csrf_legacy_tariff']=bin2hex(random_bytes(32));
try{lop_actor($koneksi,$actor,$unit);lop_require($koneksi);$record=$student?lf_one($koneksi,'SELECT t.*,s.NAMA,o.batch_id FROM legacy_op_tariffs t JOIN siswa s ON s.id=t.student_id AND s.unit_id=t.unit_id JOIN legacy_op_owners o ON o.id=t.owner_id AND o.unit_id=t.unit_id WHERE t.student_id=?',[$student]):null;if(!$record)throw new DomainException('Dasar tarif siswa tidak ditemukan.',404);
    if($_SERVER['REQUEST_METHOD']==='POST'){if(!is_string($_POST['csrf_token']??null)||!hash_equals($_SESSION['csrf_legacy_tariff'],$_POST['csrf_token']))throw new DomainException('Token CSRF tidak valid.',403);$values=$_POST;if(($_POST['action']??'')==='save'){$token=$_SESSION['legacy_tariff_preview']??[];if(($token['student']??0)!==$student||($token['expires']??0)<time()||!hash_equals($token['digest']??'',(string)($_POST['digest']??'')))throw new DomainException('Konfirmasi kedaluwarsa. Periksa ulang.');$values=json_decode((string)$_POST['payload'],true,64,JSON_THROW_ON_ERROR);$values['confirmation']=$_POST['confirmation']??'';lop_tariff_apply($koneksi,$actor,$unit,$student,(int)$_POST['version'],$values,(string)$_POST['digest'],$token['key']);$notice='Dasar tarif diperbarui. Pembayaran dan tagihan berbayar tetap dipertahankan.';$record=lf_one($koneksi,'SELECT t.*,s.NAMA,o.batch_id FROM legacy_op_tariffs t JOIN siswa s ON s.id=t.student_id AND s.unit_id=t.unit_id JOIN legacy_op_owners o ON o.id=t.owner_id AND o.unit_id=t.unit_id WHERE t.student_id=?',[$student]);}elseif(($_POST['action']??'')==='back'){$values=json_decode((string)($_POST['payload']??''),true,64,JSON_THROW_ON_ERROR);unset($_SESSION['legacy_tariff_preview']);}else{$values['expires']=time()+300;$preview=lop_tariff_preview($koneksi,$actor,$unit,$student,(int)$_POST['version'],$values);$_SESSION['legacy_tariff_preview']=['student'=>$student,'digest'=>$preview['digest'],'expires'=>$preview['expires'],'key'=>bin2hex(random_bytes(32))];}}
}catch(Throwable $e){http_response_code($e instanceof DomainException&&in_array($e->getCode(),[403,404],true)?$e->getCode():409);$error=$e instanceof DomainException?$e->getMessage():'Perubahan dibatalkan; data tetap disimpan.';}
function lte(mixed $v): string{return legacy_ui_e($v);}
?><!doctype html><html lang="id" data-palette="<?= unit_palette_for_view() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dasar Tarif Legacy</title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/backup_restore.css"><link rel="stylesheet" href="assets/css/legacy_ui.css"><link rel="stylesheet" href="assets/css/legacy_full.css"><script>document.documentElement.dataset.theme=localStorage.getItem('spp_theme')||'light';</script></head><body><div class="layout"><?php legacy_ui_sidebar(); ?><main class="main-content dbt-main"><div class="db-tools-page legacy-ui"><h1>Dasar tarif SPP siswa</h1><?php if($error): ?><p class="dbt-warning" role="alert"><?= lte($error) ?></p><?php endif; ?><?php if($notice): ?><p class="dbt-info" role="status"><?= lte($notice) ?></p><?php endif; ?><?php if(isset($record)&&$record): ?><a class="dbt-button" href="legacy_accounts.php?batch=<?= lte($record['batch_id']) ?>">Kembali ke rekening</a><section class="dbt-card"><h2><?= lte($record['NAMA']) ?></h2><p>Tarif sumber <?= lte(legacy_ui_money($record['source_amount'])) ?> · Dasar saat ini <?= lte(legacy_ui_money($record['amount'])) ?>. Koreksi pembayaran tidak mengubah dasar tarif ini.</p>
<?php if($preview): ?><section id="full-confirm" data-confirm-label="Konfirmasi dasar tarif siswa" class="lful-confirm"><h3>Ubah dasar tarif ini?</h3><p><?= lte(legacy_ui_money($preview['row']['amount'])) ?> → <?= lte(legacy_ui_money($preview['amount'])) ?> · Mulai <?= lte($preview['period']) ?></p><p><?= $preview['updated'] ?> tagihan belum dibayar diperbarui; <?= $preview['kept'] ?> tagihan dipertahankan. Tarif dan tagihan historis tidak ditulis ulang.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= lte($_SESSION['csrf_legacy_tariff']) ?>"><input type="hidden" name="version" value="<?= (int)$record['version'] ?>"><input type="hidden" name="payload" value="<?= lte(lf_json($values)) ?>"><input type="hidden" name="digest" value="<?= lte($preview['digest']) ?>"><label><input type="checkbox" name="confirmation" value="UBAH DASAR TARIF" required> Saya mengesahkan dasar tarif dan dampaknya.</label><div class="legacy-actions"><button name="action" value="back" formnovalidate class="dbt-button">Kembali Mengubah</button><button name="action" value="save" class="dbt-button dbt-button-primary">Simpan Dasar Tarif</button></div></form></section>
<?php else: ?><form method="post" class="lf-form"><input type="hidden" name="csrf_token" value="<?= lte($_SESSION['csrf_legacy_tariff']) ?>"><input type="hidden" name="version" value="<?= (int)$record['version'] ?>"><label>Dasar tarif<select name="basis"><option value="legacy" <?= ($values['basis']??'legacy')==='legacy'?'selected':'' ?>>Tarif khusus Legacy</option><option value="master" <?= ($values['basis']??'')==='master'?'selected':'' ?>>Ikuti master kelas</option></select></label><label>Nominal tarif khusus (Rp)<input name="amount" inputmode="decimal" value="<?= lte($values['amount']??$record['amount']) ?>"></label><label>Awal berlaku (YYYY-MM)<input name="period" value="<?= lte($values['period']??max(date('Y-m'),lful_next_period(lf_one($koneksi,'SELECT cutoff FROM legacy_full_batches WHERE id=?',[$record['batch_id']])['cutoff']))) ?>" required></label><label>Alasan / bukti<textarea name="reason" minlength="10" maxlength="1000" required><?= lte($values['reason']??'') ?></textarea></label><button class="dbt-button dbt-button-primary">Pratinjau Perubahan</button></form><?php endif; ?></section><?php endif; ?></div></main></div><script src="assets/js/app.js"></script><script src="assets/js/legacy_full.js"></script></body></html>
